// The package catalogue is a browser-local design demonstration.
const tiers=['minimum','standard','premium','scale & growth'];
const baseServices=[
{id:'b1',v:'bizdoc',level:0,title:'bank-ready documents',scope:'review the documents needed for a corporate account and prepare the agreed missing items.',deliver:'applicable business documents, tin support, scuml where required, letterhead and board resolution according to the approved scope.',req:'business and authorized-person details; existing documents; applicable identity and address evidence.',approved:true},
{id:'m1',v:'medialy',level:0,title:'profile plan & branding kit',scope:'give your business a clear introduction and a consistent starting identity.',deliver:'business profile plan, core message, agreed logo or existing-logo application, colours, typography and starter brand assets.',req:'business description, audience, existing logo and preferred references.',approved:true},
{id:'s1',v:'subt',level:0,title:'google business profile setup',scope:'help eligible businesses establish their business profile and submit accurate information.',deliver:'eligibility review, profile setup or improvement, service details and verification guidance.',req:'accurate business information, eligible location or service area, business-controlled account and verification evidence.',approved:true},
{id:'h1',v:'hamzury hub',level:0,title:'workspace & customer-handling essentials',scope:'help the owner use the agreed tools and handle enquiries consistently.',deliver:'short practical training and a simple enquiry-handling checklist.',req:'participant availability and tool access.',approved:false},
{id:'w1',v:'iwiin',level:0,title:'opportunity readiness check',scope:'identify whether a suitable partnership or funding route is relevant now.',deliver:'readiness checklist and a suitable next action. no award guarantee.',req:'business profile and eligibility information.',approved:false},
{id:'i1',v:'iotics',level:0,title:'practical automation needs check',scope:'assess a real physical-work problem where hardware may help.',deliver:'initial needs checklist and feasibility direction, if relevant.',req:'site context, task description and basic operating constraints.',approved:false},
{id:'b2',v:'bizdoc',level:1,title:'business document & compliance review',scope:'review business records and identify the applicable outstanding work.',deliver:'document register, gap review and selected processing under agreed scope.',req:'existing business documents and operating context.',approved:false},
{id:'m2',v:'medialy',level:1,title:'portfolio & content system',scope:'present completed projects clearly and build a practical content routine.',deliver:'portfolio structure, agreed content templates, channel plan and follow-up scripts.',req:'project photographs, permission to use client work and service details.',approved:false},
{id:'s2',v:'subt',level:1,title:'portfolio website & enquiry tracker',scope:'connect your work, enquiries and next actions in a simple system.',deliver:'agreed website pages, enquiry capture and lead-tracking configuration.',req:'approved content, brand assets, domain access and enquiry workflow.',approved:false},
{id:'h2',v:'hamzury hub',level:1,title:'team tool adoption',scope:'train the relevant team to use the selected business tools.',deliver:'role-based walkthrough, practice task and readiness check.',req:'team roles and availability.',approved:false},
{id:'w2',v:'iwiin',level:1,title:'partnership positioning',scope:'prepare an appropriate partnership approach.',deliver:'partner profile and outreach direction for agreed opportunities.',req:'capacity evidence and partnership objectives.',approved:false},
{id:'i2',v:'iotics',level:1,title:'scoped site automation plan',scope:'plan a suitable physical automation improvement where needed.',deliver:'site needs assessment, equipment proposal and installation scope.',req:'site access and operating requirements.',approved:false},
{id:'b3',v:'bizdoc',level:2,title:'compliance calendar & document governance',scope:'organize applicable recurring obligations and key business records.',deliver:'reviewed calendar, responsibility register and agreed documentation.',req:'business records and confirmed obligations.',approved:false},
{id:'m3',v:'medialy',level:2,title:'campaign & conversion management',scope:'connect campaign activity to a measured sales process.',deliver:'campaign plan, sales materials, pipeline routines and performance review.',req:'approved offer, channel access and budget review.',approved:false},
{id:'s3',v:'subt',level:2,title:'project workflow & automation',scope:'connect enquiry, costing, project delivery and reporting.',deliver:'approved workflow configuration, selected automations, testing and handover.',req:'process map, staff roles, existing tools and approved integration scope.',approved:false},
{id:'h3',v:'hamzury hub',level:2,title:'supervisor & systems training',scope:'build consistent use of the operating process.',deliver:'supervisor learning plan, practical assessment and team guidance.',req:'named supervisors and agreed operating procedures.',approved:false},
{id:'w3',v:'iwiin',level:2,title:'opportunity application support',scope:'support an eligible, selected opportunity.',deliver:'eligibility review and agreed proposal or application assistance.',req:'opportunity terms and business evidence.',approved:false},
{id:'i3',v:'iotics',level:2,title:'approved smart installation',scope:'deliver a technically reviewed physical automation project.',deliver:'agreed equipment, installation, testing and user handover.',req:'approved site survey, equipment budget and installation access.',approved:false},
{id:'b4',v:'bizdoc',level:3,title:'expansion readiness review',scope:'review documentation and applicable obligations for a planned expansion.',deliver:'gap assessment and agreed implementation scope.',req:'expansion plan, operating locations and current records.',approved:false},
{id:'m4',v:'medialy',level:3,title:'growth & retention programme',scope:'improve repeat business, referrals and measured acquisition.',deliver:'growth experiments, retention routines and management reporting.',req:'sales evidence, customer records and approved budget.',approved:false},
{id:'s4',v:'subt',level:3,title:'multi-team systems & analytics',scope:'extend proven workflows to the next business stage.',deliver:'approved permissions, integrations, dashboards and support scope.',req:'team structure, reporting needs and technical review.',approved:false},
{id:'h4',v:'hamzury hub',level:3,title:'team capability programme',scope:'close the skills gaps that limit expansion.',deliver:'role-based learning plan, supervised application and assessment.',req:'skills review and business priorities.',approved:false},
{id:'w4',v:'iwiin',level:3,title:'strategic partnerships & funding readiness',scope:'prepare for suitable growth partnerships and funding opportunities.',deliver:'opportunity pipeline, readiness work and agreed proposal support.',req:'business evidence, partnership goals and eligibility review.',approved:false},
{id:'i4',v:'iotics',level:3,title:'automation rollout & maintenance',scope:'extend successful installations with a support plan.',deliver:'approved rollout scope, commissioning and maintenance schedule.',req:'site review, operating evidence and equipment scope.',approved:false}
];
let shelf=JSON.parse(localStorage.getItem('hh-shelf-v2')||'null')||baseServices;
let basket=JSON.parse(localStorage.getItem('hh-basket-v2')||'[]'),tier=0,clientStep='proposal',clientMode=false;
let published=JSON.parse(localStorage.getItem('hh-proposal-v2')||'null');
const demoId='HH-DEMO-001';
const ventureColor={'bizdoc':'#18875b','medialy':'#c63645','subt':'#2466bf','iotics':'#a0780d','hamzury hub':'#14233b','iwiin':'#355c21'};
function serviceById(id){return (published?.services||shelf).find(s=>s.id===id)}
function badge(v){return `<span class="venturebadge" style="--vc:${ventureColor[v]||'#3b241a'}">${esc(v)}</span>`}
function serviceCard(s){return `<article class="card servicecard">${badge(s.v)}<h2>${esc(s.title)}</h2><p>${esc(s.scope)}</p><details><summary>what you receive</summary><p>${esc(s.deliver)}</p><p><b>requirements:</b> ${esc(s.req)}</p><p>price and delivery estimate require an approved quotation. external fees and conditions must be itemized.</p>${s.id==='s1'?'<p>eligibility and verification are controlled by google. setup does not guarantee approval or search ranking.</p>':''}</details><div class="row"><span class="small">${s.approved?'your minimum-package example':'proposed offer · review required'}</span><button class="${basket.includes(s.id)?'secondary':''}" onclick="chooseService('${s.id}')">${basket.includes(s.id)?'remove':'select +'}</button></div></article>`}
function chooseService(id){basket=basket.includes(id)?basket.filter(x=>x!==id):[...basket,id];localStorage.setItem('hh-basket-v2',JSON.stringify(basket));render()}
function chooseTier(n){tier=n; basket=(published?.services||shelf).filter(s=>s.level===n&&['bizdoc','medialy','subt'].includes(s.v)).map(s=>s.id);localStorage.setItem('hh-basket-v2',JSON.stringify(basket));render();toast('three core venture offers selected. adjust to suit your needs.')}
function journeyGo(s){clientStep=s;render();window.scrollTo(0,0)}
function clientShell(){return intro('your journey. a clear roadmap.','build the business in stages.','one proposal. specialist ventures. support at every step.')+`<div class="clientbar"><span>sample client · <b class="identifier">${demoId}</b></span><button class="secondary" onclick="clientMode=false;go('Overview')">holding workspace</button></div><div class="tabs">${[['proposal','your proposal'],['roadmap','your roadmap'],['payment','activation'],['requirements','onboarding'],['status','my project']].map(([s,n])=>`<button class="${s===clientStep?'active':''}" onclick="journeyGo('${s}')">${n}</button>`).join('')}</div>`}
client=function(){let h=clientShell();let clientName=published?.name||discovery.name||'sample interior design business';
if(clientStep==='proposal')return h+`<div class="proposalcover"><div class="eyebrow">business architecture · interior design & home finishing</div><h1>${esc(clientName)}</h1><h2>your work deserves a clear path to the right customers.</h2><p>our preliminary recommendation connects business documents, a clear profile and identity, and a suitable online discovery channel. start with what is missing, then build as your business develops.</p><div class="grid">${card('what we understand','an operating business wants more customers and clearer structure. social media already exists. industry-specific needs and other assets need verification.')}${card('your first priorities','confirm the offer and customer, check existing documents and assets, then choose only the support that is useful now.')}${card('how we work together','each selected service has a responsible venture. you see the combined plan, requirements, updates and deliverables in one place.')}</div><div class="notice">${published?'published browser-local demonstration snapshot':'proposal preview · not yet published'} · no prices or delivery commitments have been confirmed. the interior design scenario is an illustrative example.</div><button onclick="journeyGo('roadmap')">see my roadmap →</button></div>`;
if(clientStep==='roadmap')return h+`<div class="sectionhead"><div><div class="eyebrow">choose your starting point</div><h2>each stage brings the ventures together.</h2></div></div><div class="packagegrid">${tiers.map((t,n)=>`<button class="package ${tier===n?'selected':''}" onclick="tier=${n};render()"><span class="eyebrow">stage 0${n+1}</span><strong>${t}</strong><span>${['get ready to operate','present and manage consistently','connect and strengthen operations','support the next stage of growth'][n]}</span></button>`).join('')}</div><div class="sectionhead"><h2>${tiers[tier]} package</h2><button class="secondary" onclick="chooseTier(${tier})">select the three core offers</button></div><p>bizdoc, medialy and subt each contribute to this stage. hub, iwiin and iotics offers are added where discovery shows a relevant need. later-stage offers below are proposals for your team to approve.</p><div class="grid">${(published?.services||shelf).filter(s=>s.level===tier).map(serviceCard).join('')}</div><div class="selectiontray"><div><b>${basket.length} service${basket.length===1?'':'s'} selected</b><p class="small">${basket.map(id=>esc(serviceById(id)?.title||'')).join(' · ')||'choose a starting package or select individual services.'}</p><span class="small">total: quotation required. packages are separate stage options; selecting one does not automatically charge for earlier stages.</span></div><button onclick="if(!basket.length){toast('select at least one service');return}journeyGo('payment')">activate my selected services →</button></div>`;
if(clientStep==='payment')return h+`<div class="two"><div class="card"><span class="pill">quotation review</span><h2>your selected work.</h2>${basket.map(id=>{let s=serviceById(id);return s?`<div class="row"><div>${badge(s.v)}<h3>${esc(s.title)}</h3></div><span class="small">unpriced</span></div>`:''}).join('')||'<p>no services selected. return to your roadmap.</p>'}<div class="notice">next: your team confirms scope, price, timeline and terms. the client accepts the formal quotation, then pays. a submitted receipt stays pending until finance verifies payment.</div><button onclick="toast('demonstration quotation request recorded. no payment was taken.')">request approved quotation</button></div><div class="card"><div class="eyebrow">experience preview</div><h2>after verified payment.</h2><p>the funded scope activates. onboarding asks only for what those services need, and the work is routed to the appropriate ventures.</p><button class="secondary" onclick="journeyGo('requirements')">preview onboarding →</button><p class="small">this preview does not accept or verify payments.</p></div></div>`;
if(clientStep==='requirements')return h+`<div class="card"><span class="pill">post-payment preview</span><h2>one checklist. the right requirements.</h2><p>shared information is supplied once. each venture receives the requirements relevant to its purchased work.</p>${basket.map(id=>{let s=serviceById(id);return s?`<details open><summary>${s.v}: ${esc(s.title)}</summary><p>${esc(s.req)}</p><label>requirement notes</label><textarea placeholder="sample information only" aria-label="${esc(s.title)} requirement notes"></textarea></details>`:''}).join('')||'<p>select services in your roadmap to generate the requirements checklist.</p>'}<label>try selecting an existing logo or asset</label><input type="file" onchange="toast(this.files.length?'filename preview: '+this.files[0].name:'no file selected')"><div class="notice">preview only. documents are not uploaded. do not enter identity, payment or other sensitive information. production onboarding requires secure storage and access controls.</div><button onclick="journeyGo('status')">preview my project →</button></div>`;
return h+`<div class="two"><div class="card"><div class="eyebrow">sample client ${demoId}</div><h1>my business project</h1><p>your package is one project, with each venture accountable for its own delivery.</p>${[['bizdoc','bank-ready documents','delivered','sample document index available'],['medialy','profile plan & branding kit','awaiting your review','next action: review the proposed brand direction'],['subt','google business profile setup','waiting for verification','next action: business owner completes the required google verification']].map((x,i)=>`<div class="projectitem">${badge(x[0])}<h2>${x[1]}</h2><span class="pill">${x[2]}</span><p>${x[3]}</p><p class="small">${i===0?'delivery record: demonstration only':'expected delivery: confirmed after requirements and verification review'} · latest update: sample record</p>${i===0?'<button onclick="downloadDemo()">download sample delivery index</button>':i===1?'<button class="secondary" onclick="toast(\'sample feedback recorded. no real project was changed.\')">review / request correction</button>':''}</div>`).join('')}</div><div><div class="card"><h2>your next action is always visible.</h2><p>see completed work, pending requirements, current updates and the expected delivery date. delays and dependencies are explained rather than hidden behind a percentage.</p><div class="notice">no client goes 48 hours without an update. client id identifies the record; verified access protects it.</div></div><div class="card" style="margin-top:18px"><div class="eyebrow">next recommended stage</div><h2>standard: strengthen your portfolio and enquiry process.</h2><p>review the next step when your foundation is ready. services you already own are checked before new work is proposed.</p><button onclick="tier=1;journeyGo('roadmap')">explore the next stage →</button></div></div></div>`;}
function downloadDemo(){let blob=new Blob(['hamzury holding\nsample delivery index\nclient: '+demoId+'\n\nthis is a demonstration file, not a bank document or certificate.\nreal final files will be listed and released after quality approval.'],{type:'text/plain'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='hamzury-sample-delivery-index.txt';a.click();URL.revokeObjectURL(a.href)}
function portal(){return intro('return to your business journey','your next step is here.','open your proposal link or enter your client id to explore the sample project.')+`<div class="two"><div class="card"><h2>continue with your client id.</h2><form onsubmit="event.preventDefault();if(this.elements.cid.value.trim().toUpperCase()!==demoId){toast('use the sample id shown below');return}clientMode=true;clientStep='status';go('Client journey')"><label for="cid">client id</label><input id="cid" name="cid" placeholder="HH-DEMO-001" required><p class="small">sample id: <span class="identifier">${demoId}</span></p><button>open sample project →</button></form><div class="notice">this is a demonstration entry, not a login. a live client uses an id plus a verified sign-in method, or a secure invitation flow.</div></div><div class="card"><h2>arriving from whatsapp?</h2><p>the proposal link opens your business recommendation first. from there, see your roadmap, choose services and return to your project after activation.</p><button class="secondary" onclick="clientMode=true;clientStep='proposal';go('Client journey')">open sample proposal →</button></div></div>`}
products=function(){return intro('holding catalogue · industry shelves','one catalogue. connected packages.','edit the offers, build a client proposal, then publish a reviewable snapshot.')+`<div class="notice">industry example: interior design & home finishing. your three minimum-package examples are included. all additional venture and stage offers are editable proposals. prices and delivery times remain unconfirmed.</div><div class="tabs">${tiers.map((t,i)=>`<button class="${tier===i?'active':''}" onclick="tier=${i};render()">${t}</button>`).join('')}</div><div class="grid">${shelf.filter(s=>s.level===tier).map(s=>`<div class="card">${badge(s.v)}<h2>${esc(s.title)}</h2><p>${esc(s.deliver)}</p><span class="small">${s.approved?'supplied package example':'proposed catalogue offer'}</span><div class="tabs"><button onclick="editShelf('${s.id}')">edit offer</button></div></div>`).join('')}</div><div class="two" style="margin-top:20px"><div class="card"><h2>prepare this client’s proposal.</h2><label for="proposalname">business name</label><input id="proposalname" value="${esc(discovery.name||'sample interior design business')}"><p>publishing saves a local snapshot of these offers. later catalogue edits do not change that snapshot until you publish again.</p><button onclick="publishProposal()">publish demonstration proposal</button>${published?`<p class="small">snapshot published: ${esc(published.date)}.</p><a class="textlink" href="#proposal=${demoId}" onclick="clientMode=true;clientStep='proposal';go('Client journey')">open client proposal →</a><div class="notice">whatsapp draft: your business proposal is ready. review our recommendation and choose your next step.<br><span class="identifier">${esc(location.origin+location.pathname+'#proposal='+demoId)}</span><br>demo link only. private site access remains unchanged; browser-local edits are not shared across devices.</div>`:''}</div><div class="card"><h2>catalogue publishing standard</h2><p>each venture owns its offers. holding reviews the package logic. before live publication, confirm the price, scope, timing, requirements and responsible delivery team.</p><button class="secondary" onclick="editShelf('new')">add an offer to this stage +</button><p class="small">production catalogue: industry tags and reusable service records will support many business types without duplicate service definitions.</p></div></div>`}
function editShelf(id){let s=shelf.find(x=>x.id===id)||{id:'new',v:'bizdoc',title:'',scope:'',deliver:'',req:'',level:tier};$('#app').innerHTML=intro('catalogue editor',id==='new'?'add a venture offer.':'edit the service standard.','browser-local draft. confirmed prices and timelines are required before live sale.')+`<form class="card" onsubmit="saveShelf(event,'${s.id}')"><label>venture</label><select name="v">${ventures.map(v=>`<option ${v[0]===s.v?'selected':''}>${v[0]}</option>`).join('')}</select><label>package stage</label><select name="level">${tiers.map((t,i)=>`<option value="${i}" ${s.level===i?'selected':''}>${t}</option>`).join('')}</select><label>service title</label><input name="title" value="${esc(s.title)}" required><label>why it matters</label><textarea name="scope" required>${esc(s.scope)}</textarea><label>deliverables</label><textarea name="deliver" required>${esc(s.deliver)}</textarea><label>requirements</label><textarea name="req" required>${esc(s.req)}</textarea><div class="tabs"><button>save catalogue draft</button><button type="button" onclick="render()">cancel</button></div></form>`}
function saveShelf(e,id){e.preventDefault();let d=Object.fromEntries(new FormData(e.target));d.level=Number(d.level);if(id==='new'){d.id='offer-'+Date.now();d.approved=false;shelf.push(d)}else{let n=shelf.findIndex(x=>x.id===id);shelf[n]={...shelf[n],...d}}localStorage.setItem('hh-shelf-v2',JSON.stringify(shelf));render();toast('catalogue draft saved. publish to update the sample proposal.')}
function publishProposal(){published={name:$('#proposalname').value||'sample business',date:new Date().toLocaleString('en-NG',{timeZone:'Africa/Lagos'}),services:structuredClone(shelf)};localStorage.setItem('hh-proposal-v2',JSON.stringify(published));render();toast('demonstration proposal snapshot published in this browser')}
menus.splice(3,0,'My project');
const oldRender=render;
render=function(){if(page==='My project'){$('#app').innerHTML=portal()}else oldRender();document.body.classList.toggle('client-mode',clientMode);document.querySelectorAll('.mark').forEach(el=>{let name=el.parentElement.querySelector('h3,h2')?.textContent;let match=ventures.find(v=>v[0]===name);if(match)el.outerHTML=`<img class="venturelogo" src="assets/${match[0]==='hamzury hub'?'hub':match[0]}.png" alt="${match[0]}">`});document.querySelectorAll('#app label:not([for])').forEach((l,i)=>{let c=l.nextElementSibling;if(c&&c.matches('input,select,textarea')){c.id=c.id||'field-'+i;l.htmlFor=c.id}})};
nav=function(){$('#nav').innerHTML=menus.map(x=>`<button class="${page===x?'active':''}" onclick="clientMode=false;go('${x}')">${x.toLowerCase()}</button>`).join('');$('#crumb').textContent=page.toLowerCase()};
$('.brand').innerHTML='<img src="assets/hamzury.png" alt="hamzury holding" style="width:175px;height:auto"><small>holding operating system</small>';
function openHash(){if(location.hash==='#proposal='+demoId){clientMode=true;clientStep='proposal';go('Client journey')}else if(location.hash==='#project='+demoId){clientMode=true;clientStep='status';go('Client journey')}}
window.addEventListener('hashchange',openHash);nav();render();openHash();
